using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;

// --- Tool implementations -----------------------------------------------

/// <summary>Tools the research agent can call during its investigation.</summary>
static class ResearchTools
{
    private static readonly HttpClient Http = new();
    private static readonly List<string> Notes = [];

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍 Searching: {query}");
        Console.ResetColor();

        try
        {
            // Use Wikipedia API as a freely-available search source.
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=5&format=json";
            var json = await Http.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var results = doc.RootElement.GetProperty("query").GetProperty("search");

            var sb = new StringBuilder();
            foreach (var r in results.EnumerateArray())
            {
                var title = r.GetProperty("title").GetString();
                var snippet = r.GetProperty("snippet").GetString();
                // Strip HTML tags from MediaWiki snippets.
                snippet = System.Text.RegularExpressions.Regex.Replace(snippet ?? "", "<.*?>", "");
                sb.AppendLine($"• {title}: {snippet}");
            }

            return sb.Length > 0 ? sb.ToString() : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note for later use in the summary.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved ({Notes.Count} total)");
        Console.ResetColor();
        return $"Note saved. You now have {Notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < Notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {Notes[i]}");
        return sb.ToString();
    }

    public static void ClearNotes() => Notes.Clear();
}

// --- Main ---------------------------------------------------------------

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬  AI Research Agent  🔬      ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine($"Model: {model}");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

// Build the chat client with automatic function invocation.
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable."))
        .GetChatClient(model)
        .AsIChatClient())
    .UseFunctionInvocation()
    .Build();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    ResearchTools.ClearNotes();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. When given a topic you MUST:
            1. Use the SearchWeb tool multiple times with different queries to gather information.
            2. Use SaveNote to record key facts and findings as you go.
            3. Use GetNotes to review what you've collected.
            4. Finally, write a well-structured summary with sections and citations.
            Always search at least 2-3 different queries to get broad coverage.
            """),
        new(ChatRole.User, $"Research this topic and provide a comprehensive summary: {topic}"),
    };

    var options = new ChatOptions { Tools = [.. tools] };

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching... (agent is searching and taking notes)");
    Console.ResetColor();

    var response = await client.GetResponseAsync(messages, options);

    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.WriteLine("\n═══ Research Summary ═══\n");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

